from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

doc = Document()
sec = doc.sections[0]
sec.left_margin = sec.right_margin = Inches(1)
sec.top_margin = sec.bottom_margin = Inches(1)
st = doc.styles["Normal"]
st.font.name = "Times New Roman"; st.font.size = Pt(11)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
st.paragraph_format.space_after = Pt(6)
for h, sz in (("Heading 1", 13), ("Heading 2", 12), ("Heading 3", 11)):
    s = doc.styles[h]; s.font.name = "Times New Roman"; s.font.size = Pt(sz); s.font.bold = True
    s.font.color.rgb = RGBColor(0x1F, 0x2A, 0x44)
    s.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    s.paragraph_format.space_before = Pt(12); s.paragraph_format.space_after = Pt(6)

def _runs(p, text):
    # **bold** segments
    parts = text.split("**")
    for i, part in enumerate(parts):
        if part:
            r = p.add_run(part)
            if i % 2 == 1: r.bold = True
    return p

def H1(t): doc.add_heading(t, level=1)
def H2(t): doc.add_heading(t, level=2)
def H3(t): doc.add_heading(t, level=3)
def P(t, italic=False, indent=None, align=None):
    p = doc.add_paragraph(); _runs(p, t)
    if italic:
        for r in p.runs: r.italic = True
    if indent: p.paragraph_format.left_indent = Inches(indent)
    if align == "j": p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    return p
def Q(t):
    p = doc.add_paragraph(); _runs(p, t)
    p.paragraph_format.left_indent = Inches(0.5); p.paragraph_format.right_indent = Inches(0.5)
    for r in p.runs: r.font.size = Pt(10)
    return p
def B(t, level=0):
    p = doc.add_paragraph(style="List Bullet" if level == 0 else "List Bullet 2"); _runs(p, t); return p
def N(t):
    p = doc.add_paragraph(style="List Number"); _runs(p, t); return p

def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd"); shd.set(qn("w:val"), "clear"); shd.set(qn("w:color"), "auto"); shd.set(qn("w:fill"), hexcolor)
    tcPr.append(shd)

def T(headers, rows, widths=None, fs=9):
    t = doc.add_table(rows=1, cols=len(headers))
    t.style = "Table Grid"; t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ""
        r = c.paragraphs[0].add_run(h); r.bold = True; r.font.size = Pt(fs)
        shade(c, "D9E2F3")
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            p = cells[i].paragraphs[0]; _runs(p, str(v))
            for r in p.runs: r.font.size = Pt(fs)
            p.paragraph_format.space_after = Pt(0)
    if widths:
        for row in t.rows:
            for i, w in enumerate(widths):
                row.cells[i].width = Inches(w)
    doc.add_paragraph()
    return t
EOF
echo ok'

